mapper.select:
SELECT s.*, v.voucher_no, v.voucher_date
FROM fin_bank_statement s
LEFT JOIN fin_voucher_entry e ON e.id = s.entry_id
LEFT JOIN fin_voucher v ON v.id = e.voucher_id
WHERE s.account_id = #{accountId}
AND s.txn_date >= #{begin}
AND s.txn_date <= #{end}
ORDER BY s.txn_date, s.id

SELECT e.id AS "entryId", v.id AS "voucherId", v.voucher_no AS "voucherNo", v.voucher_date AS "voucherDate",
       e.summary AS "summary", e.debit - e.credit AS "amount",
       CASE WHEN EXISTS (SELECT 1 FROM fin_bank_statement s WHERE s.entry_id = e.id) THEN 1 ELSE 0 END AS "matched"
FROM fin_voucher_entry e
JOIN fin_voucher v ON v.id = e.voucher_id
WHERE e.account_id = #{accountId}
AND v.voucher_date >= #{begin}
AND v.voucher_date <= #{end}
ORDER BY v.voucher_date, v.id, e.seq

SELECT COALESCE(SUM(t.amount), 0) FROM (
    SELECT e.debit - e.credit AS amount
    FROM fin_voucher_entry e
    JOIN fin_voucher v ON v.id = e.voucher_id
    WHERE e.account_id = #{accountId} AND v.voucher_date <= #{asOf}
    UNION ALL
    SELECT o.debit - o.credit FROM fin_account_opening o WHERE o.account_id = #{accountId}
) t
